CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "cff11fda-5f0d-450b-8113-6277664fb8e5",
  "snapshot_timestamp": "2026-05-21T19:38:25Z",
  "ticket_id": "615f-fad3",
  "items": [
    {
      "original_text": "Sprint Phase 1 (Preplanning Gate Step 2a) runs a 3-tier SC coverage check \u2014 haiku first pass, sonnet targeted pass, opus final arbiter \u2014 before Phase 3 batch preparation, for epic-typed tickets with existing children",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system process that runs as ongoing behavior before batch preparation, not a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Haiku confirms only SCs it can validate by citing a specific covering child; any SC it cannot cite a covering child for is escalated to sonnet",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior and validation rule that persists after implementation, not a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Sonnet evaluates each escalated SC independently (without knowledge of why it was escalated) and returns COVERED, MISSING, or UNSURE per SC; UNSURE SCs are passed to opus",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior where Sonnet processes escalated SCs with specific evaluation logic and return states"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Opus is the final arbiter for UNSURE SCs, returning COVERED or MISSING; opus defaults to COVERED when coverage intent is plausible but wording is ambiguous",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior and decision-making rule that persists after implementation, not a one-time task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When any SC is determined MISSING post-cascade, sprint writes a REPLAN_TRIGGER: sc_coverage comment on the epic listing the missing SCs, then routes to /dso:preplanning (at least one child has type:story) or /dso:implementation-plan (all children have type:task)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior and routing logic that persists after implementation, not a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When all SCs are COVERED post-cascade, sprint proceeds normally to Phase 3 without invoking preplanning",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior condition that determines ongoing sprint workflow once established"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Tests cover each tier's routing logic \u2014 including a test where an epic with 5 SCs and children covering only 3 triggers gap detection and routes to the correct decomposition skill based on children type",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system property that tests will verify\u2014the ability to detect gaps and route correctly\u2014rather than a one-time completion of test writing"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Dedicated prompt files exist for each tier (haiku, sonnet, opus) defining input schema (SC list + children descriptions) and output schema (per-SC verdict + escalation list), referenced from the sprint SKILL.md step",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system state where prompt files are organized and exist as persistent artifacts that define schemas and are referenced in documentation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
